svg.script:
(() => {
	const channel = "cat-flap-viewer";
	const root = document.documentElement;
	const sheets = [
		document.getElementById("sheet-geometry"),
		document.getElementById("sheet-actuators"),
		document.getElementById("sheet-pcb"),
		document.getElementById("sheet-sensors")
	];
	const originalTransforms = ["", "translate(0 900)", "translate(0 1800)", "translate(0 2700)"];
	const layers = sheets.map(() => ({ visible: true }));
	const dividers = Array.from(document.querySelectorAll(".sheet-divider"));
	let folded = true;
	let weights = [100, 0, 0, 0];
	let scrollPosition = 0;

	function visibleIndices() {
		return layers.flatMap((layer, index) => layer.visible ? [index] : []);
	}

	function shareEvenly(amount, recipients, subtract = false) {
		let remaining = amount;
		let available = recipients.filter(index => !subtract || weights[index] > 0);
		while (remaining > 0 && available.length) {
			const base = Math.floor(remaining / available.length);
			const extra = remaining % available.length;
			if (!subtract) {
				available.forEach((index, slot) => { weights[index] += base + (slot < extra ? 1 : 0); });
				remaining = 0;
				continue;
			}
			let removed = 0;
			available.forEach((index, slot) => {
				const reduction = Math.min(weights[index], base + (slot < extra ? 1 : 0));
				weights[index] -= reduction;
				removed += reduction;
			});
			remaining -= removed;
			available = available.filter(index => weights[index] > 0);
			if (!removed) break;
		}
	}

	function syncScrollPosition() {
		const active = visibleIndices();
		if (active.length < 2) {
			scrollPosition = 0;
			return;
		}
		scrollPosition = active.reduce((position, index, order) => position + order * weights[index], 0) / 100;
	}

	function setLayerOpacity(index, requested) {
		if (!layers[index].visible) return;
		const target = Math.max(0, Math.min(100, Math.round(requested)));
		const difference = target - weights[index];
		if (difference > 0) {
			const donors = visibleIndices().filter(other => other !== index && weights[other] > 0);
			shareEvenly(difference, donors, true);
			weights[index] = 100 - weights.reduce((sum, weight, other) => sum + (other === index ? 0 : weight), 0);
		} else if (difference < 0) {
			let recipients = visibleIndices().filter(other => other !== index && weights[other] > 0);
			if (!recipients.length) recipients = visibleIndices().filter(other => other !== index);
			if (!recipients.length) return;
			weights[index] = target;
			shareEvenly(-difference, recipients);
		}
		syncScrollPosition();
	}

	function setLayerVisible(index, visible) {
		if (layers[index].visible === visible) return;
		if (!visible) {
			const recipients = visibleIndices().filter(other => other !== index);
			if (!recipients.length) return;
			const shareRecipients = recipients.filter(other => weights[other] > 0);
			const freed = weights[index];
			layers[index].visible = false;
			weights[index] = 0;
			shareEvenly(freed, shareRecipients.length ? shareRecipients : recipients);
		} else {
			layers[index].visible = true;
		}
		syncScrollPosition();
	}

	function publish() {
		window.parent.postMessage({
			channel,
			folded,
			dominant: dominantLayer(),
			scrollPosition,
			layers: layers.map((layer, index) => ({ ...layer, opacity: weights[index] }))
		}, "*");
	}

	function dominantLayer() {
		const maximum = Math.max(...weights);
		const leaders = weights.flatMap((weight, index) => weight === maximum ? [index] : []);
		return leaders.length === 1 ? leaders[0] : -1;
	}

	function apply() {
		const dominant = dominantLayer();
		root.setAttribute("viewBox", folded ? "0 0 1600 900" : "0 0 1600 3600");
		root.setAttribute("height", folded ? "900" : "3600");
		root.style.height = folded ? "100%" : "auto";
		for (let index = 0; index < sheets.length; index += 1) {
			const sheet = sheets[index];
			sheet.setAttribute("transform", folded ? "translate(0 0)" : originalTransforms[index]);
			sheet.style.display = layers[index].visible ? "" : "none";
			sheet.style.opacity = folded ? String(weights[index] / 100) : "1";
			sheet.querySelectorAll(".dimensions").forEach(element => {
				const measurementOpacity = folded ? Math.max(0, Math.min(1, (weights[index] - 75) / 5)) : 1;
				element.style.display = index === dominant && (!folded || weights[index] >= 75) ? "" : "none";
				element.style.opacity = String(measurementOpacity);
				element.style.transition = "opacity 40ms linear";
			});
			sheet.querySelectorAll(".label").forEach(element => {
				if (element.classList.contains("dimensions")) return;
				element.style.display = folded && index !== dominant ? "none" : "";
			});
		}
		dividers.forEach(divider => { divider.style.display = folded ? "none" : ""; });
		publish();
	}

	function roll(deltaY) {
		const active = visibleIndices();
		if (active.length < 2) return;
		scrollPosition = Math.max(0, Math.min(active.length - 1, scrollPosition + deltaY / 360));
		const lower = Math.floor(scrollPosition);
		const upper = Math.min(active.length - 1, lower + 1);
		const upperShare = Math.round((scrollPosition - lower) * 100);
		weights = weights.map(() => 0);
		weights[active[lower]] = 100 - upperShare;
		weights[active[upper]] += upperShare;
		apply();
	}

	window.addEventListener("message", event => {
		const message = event.data;
		if (event.source !== window.parent || !message || message.channel !== channel) return;
		switch (message.action) {
			case "sync":
				break;
			case "fold":
				folded = Boolean(message.value);
				if (folded) syncScrollPosition();
				break;
			case "layer":
				if (typeof message.value.visible === "boolean") setLayerVisible(message.index, message.value.visible);
				if (typeof message.value.opacity === "number") setLayerOpacity(message.index, message.value.opacity);
				break;
			case "scroll":
				if (folded) roll(message.deltaY);
				return;
		}
		apply();
	});

	root.addEventListener("wheel", event => {
		if (!folded) return;
		event.preventDefault();
		roll(event.deltaY);
	}, { passive: false });

	apply();
})();
